    line = max(set(v for row in grid for v in row), key=lambda c: sum(row.count(c) for row in grid))
    background = next(c for c in set(v for row in grid for v in row) if c != line)
    seen = set()
    stack = [(r, c) for r in range(h) for c in range(w)
             if (r == 0 or c == 0 or r == h - 1 or c == w - 1)
             and grid[r][c] == background]
    while stack:
        r, c = stack.pop()
        if (r, c) in seen:
            continue
        seen.add((r, c))
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background and (nr,nc) not in seen:
                stack.append((nr,nc))
